/**
 * Smaller copies of approved local photographs, generated by scripts/responsive-images.py as
 * `<name>-<width>w.webp`. The source file stays the largest candidate, so high-density screens
 * receive exactly the image they did before; only smaller screens get a downscaled copy.
 */
const LOCAL_VARIANTS: Record<string, {width: number; widths: number[]}> = {
  "/images/editorial/iqon-coastal-mobile-v32.webp": {width: 941, widths: [640, 750]},
  "/images/editorial/supplement-campaign-mobile-v12.webp": {width: 1086, widths: [750]},
  "/images/editorial/news-reading-labels-iqon-v11.webp": {width: 1536, widths: [480, 768]},
  "/images/editorial/daily-water-v24.webp": {width: 1536, widths: [480, 768]},
  "/images/editorial/skincare-ritual-v26.webp": {width: 1536, widths: [480, 768]},
  "/images/supplements/12_hero_creatine_scoop.webp": {width: 1450, widths: [480, 720]},
  "/images/supplements/16_hero_colostrum_open.webp": {width: 1450, widths: [480, 720]},
};

/** `srcSet` for a local photograph with generated variants; undefined leaves the `<img>` unchanged. */
export function localSrcSet(src: string) {
  const variants = LOCAL_VARIANTS[src];
  if (!variants) return undefined;
  return [...variants.widths.map(w => `${src.replace(/\.webp$/, `-${w}w.webp`)} ${w}w`), `${src} ${variants.width}w`].join(", ");
}

const SHOPIFY_WIDTHS = [360, 540, 720, 960];

/** Shopify CDN resizes on request (`width=`), keeping aspect ratio and serving WebP/AVIF to browsers that accept it. */
export function shopifySrcSet(src: string) {
  let url: URL;
  try {url = new URL(src);} catch {return undefined;}
  if (url.protocol !== "https:" || url.hostname !== "cdn.shopify.com") return undefined;
  return SHOPIFY_WIDTHS.map(w => {url.searchParams.set("width", String(w)); return `${url.href} ${w}w`;}).join(", ");
}
